from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind, step = parts[0], int(parts[1])
    result = []
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    if kind == "WEEKLY":
        selected = sorted(weekdays[wd] for wd in parts[2].split(","))
        week_start = first - timedelta(days=first.weekday())

        while True:
            for wd in selected:
                candidate = week_start + timedelta(days=wd)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            week_start += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        number = int(parts[2])
        weekday_rule = len(parts) == 4
        target_wd = weekdays[parts[3]] if weekday_rule else 0

        while len(result) < count:
            year, zero_based_month = divmod(month_index, 12)
            month = zero_based_month + 1
            first_wd, days_in_month = monthrange(year, month)

            if not weekday_rule:
                day = days_in_month if number == -1 else number
            elif number == -1:
                last_wd = (first_wd + days_in_month - 1) % 7
                day = days_in_month - (last_wd - target_wd) % 7
            else:
                day = 1 + (target_wd - first_wd) % 7 + 7 * (number - 1)

            if day <= days_in_month:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())

            month_index += step

        return result

    month, day = map(int, parts[2].split("-"))
    year = first.year

    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= first:
                result.append(candidate.isoformat())
        year += step

    return result
